+-- A known user id gave power over its user: a group admin could add it to their group,
+-- and a space editor could grant their space or a resource to it.
+
+COMMENT ON TABLE public.group_membership IS 'A group membership table. Clients cannot insert rows, and can update only admin: the create-group edge function adds the first admin with the service role, and accept_group_invitation adds invited members.';
+
+-- Updating member_id or group_id of an existing row would add a member as surely as an insert.
+REVOKE INSERT, UPDATE ON TABLE public.group_membership FROM authenticated;
+GRANT UPDATE (admin) ON TABLE public.group_membership TO authenticated;
+DROP POLICY IF EXISTS group_membership_insert_policy ON public.group_membership;
+
+DROP POLICY IF EXISTS space_access_insert_policy ON public."SpaceAccess";
+CREATE POLICY space_access_insert_policy ON public."SpaceAccess" FOR INSERT WITH CHECK (
+    space_id = any((SELECT public.my_space_ids('editor'))::bigint[])
+    AND account_uid IN (SELECT public.my_user_accounts())
+);
+COMMENT ON POLICY space_access_insert_policy ON public."SpaceAccess" IS 'Editors grant their space only to themselves or to a group they belong to, so a known user id gives no power over that user.';
+
+DROP POLICY IF EXISTS space_access_update_policy ON public."SpaceAccess";
+CREATE POLICY space_access_update_policy ON public."SpaceAccess" FOR UPDATE USING (
+    space_id = any((SELECT public.my_space_ids('editor'))::bigint[])
+) WITH CHECK (
+    space_id = any((SELECT public.my_space_ids('editor'))::bigint[])
+    AND account_uid IN (SELECT public.my_user_accounts())
+);
+COMMENT ON POLICY space_access_update_policy ON public."SpaceAccess" IS 'The updated row must pass the insert check. So an editor cannot change the permissions of a grant to another user, though they can delete it.';
+
+DROP POLICY IF EXISTS resource_access_insert_policy ON public."ResourceAccess";
+CREATE POLICY resource_access_insert_policy ON public."ResourceAccess" FOR INSERT WITH CHECK (
+    space_id = any((SELECT public.my_space_ids('editor'))::bigint[])
