const getNodeInstanceSourceLocalIds = async ({
  supabaseClient,
  spaceId,
}: {
  supabaseClient: DGSupabaseClient;
  spaceId: number;
}): Promise<{ synced: Set<string>; shared: Set<string> }> => {
  const sharedResources = await getAllPages(
    supabaseClient
      .from("ResourceAccess")
      .select("source_local_id")
      .eq("space_id", spaceId)
      .order("source_local_id")
      .order("account_uid"),
    1000,
  );

  if (!Array.isArray(sharedResources)) throw sharedResources;

  const sharedSourceLocalIds = new Set(
    sharedResources.map((resource) => resource.source_local_id),
  );
  const syncedInstanceConcepts = await getAllPages(
    supabaseClient
      .from("my_concepts")
      .select("source_local_id")
      .eq("space_id", spaceId)
      .eq("is_schema", false)
      .eq("is_relation", false)
      .order("source_local_id"),
    1000,
    // Importers need the end types to map the triple to their own node types.
    const groupRelationEndTypeIds = new Set(
      relationTripleSchemas
        .filter((rs3) => groupRelationTripleSchemaIds.has(rs3.localId))
        .flatMap((rs3) => [rs3.sourceType, rs3.destinationType]),
    );
    const groupResourceIds = [
      ...new Set([
        ...resourceIds,
        ...groupRelationIds,
        ...groupRelationTripleSchemaIds,
        ...groupRelationEndTypeIds,
      ]),
    ];
    resourceAccesses.push(
      ...groupResourceIds.map((sourceLocalId) => ({
        account_uid: groupId,
        source_local_id: sourceLocalId,
        space_id: spaceId,
      })),
    );
  }

  const grantRes = await client
    .from("ResourceAccess")
    .upsert(resourceAccesses, { ignoreDuplicates: true });
  if (!isIgnorableUpsertError(grantRes.error)) {
    internalError({ error: grantRes.error });
    result.failedGroupIds.push(...groupIds);
    return result;
  }

  result.okGroupIds = groupIds;
  result.publishedRelationTripleSchemaUids = relationTripleSchemaUids;
  result.publishedRelationUids = relationUids;
  result.publishedNodeSchemaUids = [...nodeSchemaUids];
  result.publishedNodeUids = nodeUids;

  return result;
};

